 "content": "def transform(grid):
    """Fill the framed panels with the matching colored shape from the right."""
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    # The left puzzle board is the initial run of frame-colored cells on its top edge.
    left_w = 0
    while left_w < w and grid[0][left_w] == frame:
        left_w += 1
    if left_w == 0 or left_w == w:
        raise ValueError("could not locate left board / separator")

    # Collect the colored source silhouettes to the right, cropped to their bounds.
    colors = sorted({grid[r][c] for r in range(h) for c in range(left_w, w)
                     if grid[r][c] != 0})
    shapes = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(left_w, w)
                 if grid[r][c] == color]
        r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
        c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
        shapes[color] = [[grid[r][c] == color for c in range(c0, c1 + 1)]
                         for r in range(r0, r1 + 1)]

    # Full horizontal frame rows are the shared boundaries of the panels.
    boundaries = [r for r in range(h)
                  if all(grid[r][c] == frame for c in range(left_w))]
    out = [row[:left_w] for row in grid]
    for top, bottom in zip(boundaries, boundaries[1:]):
        if bottom <= top + 1:
            continue
        target = [[grid[r][c] == 0 for c in range(1, left_w - 1)]
                  for r in range(top + 1, bottom)]
        target_h, target_w = len(target), len(target[0])
        match = None
        for color, shape in shapes.items():
            sh, sw = len(shape), len(shape[0])
            if sh > target_h or sw > target_w:
                continue
            for dr in range(target_h - sh + 1):
                for dc in range(target_w - sw + 1):
                    placed = [[False] * target_w for _ in range(target_h)]
                    for r in range(sh):
                        for c in range(sw):
                            placed[dr + r][dc + c] = shape[r][c]
                    if placed == target:
                        match = color
                        break
                if match is not None:
                    break
            if match is not None:
                break
        if match is None:
            raise ValueError(f"no source shape matches panel rows {top}:{bottom}")
        for r in range(top + 1, bottom):
            for c in range(1, left_w - 1):
                if grid[r][c] == 0:
                    out[r][c] = match
    return out
